import{_ as r,l as s,o as a,c as l,v as o,p as B,x as n,d as i,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Qwen3 技术报告","description":"","frontmatter":{"title":"Qwen3 技术报告","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-report.md","filePath":"llm/qwen3-report.md","lastUpdated":1789023840000}'),c={name:"llm/qwen3-report.md"};function p(d,e,m,k,A,S){const t=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="qwen3-技术报告" tabindex="-1">Qwen3 技术报告 <a class="header-anchor" href="#qwen3-技术报告" aria-label="Permalink to &quot;Qwen3 技术报告&quot;">​</a></h1><div class="epigraph"><p>相对 Qwen2.5，Qwen3 把预训练 token 大约翻倍、语种扩大到约 119 种；稠密与 MoE 共用去掉 QKV bias、加上 QK-Norm 的注意力配方。</p><footer>—— Yang 等，Qwen3 Technical Report，arXiv:2505.09388</footer></div><p><a href="/llm/qwen3">Qwen3</a> 专文写思考 / 非思考融合与 MoE 的 128 专家 top-8。本篇对着 <strong>2505.09388</strong> 写报告里那半边：<strong>36T 怎么来的、三阶段预训练、实例级配比、架构表、基座分数如何对上 2.5 的更大稠密模型</strong>。后训练四段与 <code>/think</code> 开关只在需要区分 Base / Instruct 时点到，细节不重复。2025 年 7 月的 2507 快照与 Qwen3-Next 不写进本报告的默认列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2.5 的开源主线是稠密 0.5B–72B、18T token、QKV bias 仍在。3 要同时做到：更小的稠密档打过 2.5 更大档、MoE 成为可下载一等公民、以及多语从约 29 种扩到 119 种。若只加 token 不加配比，18T→36T 会变成网页噪声翻倍。报告的问题是：<strong>如何用标注过的 30T+ token 做实例级混合</strong>，再用三阶段课程把世界知识、STEM 与 32k 窗口分开买，而不是从头就按 32k 训。</p><p>第二个问题是结构差分必须小到生态可迁移，又大到训练能稳。答案写在注意力：去 bias、加 QK-Norm；MoE 去共享专家、换全局 batch 负载损失。词表 151,669 的字节级 BPE 保持家族连续。</p><h3 id="稠密表与-moe-表要分开读" tabindex="-1">稠密表与 MoE 表要分开读 <a class="header-anchor" href="#稠密表与-moe-表要分开读" aria-label="Permalink to &quot;稠密表与 MoE 表要分开读&quot;">​</a></h3><p>报告表 1（稠密）：0.6B / 1.7B 为 28 层、16/8 头、绑定嵌入、上下文 32k；4B 起 36 层、32/8 头，4B 仍绑嵌入且窗口 128k；8B 不再绑嵌入；14B 为 40 层 40/8；32B 为 64 层 64/8，窗口 128k。表 2（MoE）：30B-A3B 为 48 层、32/4 头、128/8 专家、128k；235B-A22B 为 94 层、64/4 头、同样 128/8 专家。A22B 指约 22B 激活，不是 22 个专家。小模型 14B 及以下与 30B-A3B 的思考能力大量来自强到弱蒸馏，见产品专文，不要用旗舰 AIME 宣传 0.6B。</p><p><span class="marginnote">预训练课程把窗口先做到 32,768；推理再靠 YaRN 与 Dual Chunk Attention 大约四倍，Instruct 常规到 128k。不要把 128k 写成「预训练就是 128k 满注意力」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：约 <strong>36T</strong> token，相对 2.5 的 18T 约两倍，语种约三倍。扩量两条公开管线：用 <a href="/llm/qwen25-vl">Qwen2.5-VL</a> 从 PDF 类文档抽文本，再用 Qwen2.5 润色，得到万亿级高质量文本；用 Qwen2.5、<a href="/llm/qwen25-math">Math</a>、<a href="/llm/qwen25-coder">Coder</a> 合成教材、问答、代码片段。另加多语爬取。超过 30T token 被多维标注（教育价值、领域、安全等），在小代理模型上做消融，<strong>按实例而不是按数据源</strong>调混合——这是相对「按域名调配比」的方法差分。</p><h3 id="三阶段-s1-通识、s2-推理、s3-长上下文" tabindex="-1">三阶段：S1 通识、S2 推理、S3 长上下文 <a class="header-anchor" href="#三阶段-s1-通识、s2-推理、s3-长上下文" aria-label="Permalink to &quot;三阶段：S1 通识、S2 推理、S3 长上下文&quot;">​</a></h3><p><strong>S1（General）</strong>：全体尺寸在序列长度 4,096 上吃 <strong>超过 30T</strong>，覆盖 119 种语言与方言，建立语言与世界知识。<strong>S2（Reasoning）</strong>：提高 STEM、代码、推理与合成数据比例，再训约 <strong>5T</strong>，仍为 4k 长度，并加快学习率衰减。<strong>S3（Long Context）</strong>：高质量长文本 <strong>数千亿</strong> token，序列 32,768；其中约 75% 落在 16k–32k，25% 在 4k–16k。RoPE 基数用 ABF 从 (10^4) 提到 (10^6)；推理期 <a href="/llm/yarn">YaRN</a> 与 <a href="/llm/dual-chunk-attention">DCA</a> 再把容量乘四。缩放律被用来分别给稠密与 MoE 调学习率日程与 batch，而不是只抄 2.5 的表。</p>',13)),(a(),B(h,null,{default:n(()=>[E(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PDF%5B%22PDF%20%E2%86%92%20Qwen2.5-VL%20OCR%20%E2%86%92%20Qwen2.5%20%E6%B6%A6%E8%89%B2%22%5D%20--%3E%20MIX%5B%22%E5%AE%9E%E4%BE%8B%E7%BA%A7%E6%A0%87%E6%B3%A8%E4%B8%8E%E9%85%8D%E6%AF%94%22%5D%0A%20%20SYN%5B%22Math%2FCoder%20%E5%90%88%E6%88%90%22%5D%20--%3E%20MIX%0A%20%20WEB%5B%22%E7%BD%91%E9%A1%B5%20%2F%20%E4%B9%A6%20%2F%20%E5%A4%9A%E8%AF%AD%22%5D%20--%3E%20MIX%0A%20%20MIX%20--%3E%20S1%5B%22S1%EF%BC%9A%3E30T%20%40%204k%22%5D%0A%20%20S1%20--%3E%20S2%5B%22S2%EF%BC%9A~5T%20STEM%2F%E4%BB%A3%E7%A0%81%20%40%204k%22%5D%0A%20%20S2%20--%3E%20S3%5B%22S3%EF%BC%9A%E6%95%B0%E7%99%BE%20B%20%40%2032k%20%2B%20ABF%22%5D%0A%20%20S3%20--%3E%20YARN%5B%22%E6%8E%A8%E7%90%86%20YaRN%20%2B%20DCA%20%E2%86%92%20128k%22%5D%0A%20%20S3%20--%3E%20BASE%5B%22Base%20%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20BASE%20--%3E%20PT%5B%22%E5%90%8E%E8%AE%AD%E7%BB%83%EF%BC%9A%E6%80%9D%E8%80%83%E8%9E%8D%E5%90%88%EF%BC%8C%E8%A7%81%20Qwen3%20%E4%B8%93%E6%96%87%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>基座评测是报告给的「配方是否值」的证据：Qwen3-32B-Base 对上 Gemma-3-27B、Qwen2.5-32B，甚至拿 2.5-72B 与 Llama-4-Scout 当强基线；叙事是 STEM/代码上 3 的较小 Base 打过 2.5 的较大 Base。235B-A22B-Base 再对 Qwen2.5-Plus-Base、Llama-4-Maverick、DeepSeek-V3 Base 与 2.5-72B-Base。MoE Base 用约 10% 激活对标 2.5 稠密，这是服务侧省 FLOP 的主句。边侧 8B/4B/1.7B/0.6B-Base 相对同尺寸 2.5、Llama-3、Gemma-3 继续在多数集上领先，且 8B/4B/1.7B 在过半基准上打过更大一档的 2.5。具体分数随表 3–8，引用应钉 Base 而非 Instruct，也不要把思考模式的 AIME 贴到 Base 检查点上。</p><p><span class="marginnote">36T 不是「36T 本高质量书」。报告自己把合成、OCR 网页、多语爬取并列。过滤与标注是质量故事，规模只是分子。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>实例级混合的机制是：每条样本带多维标签，代理模型上的消融决定「这条进 S1 还是下调」，避免整个 Common Crawl 域名被一刀切。代价是标注系统本身成为不可开源的核心资产。S2 提高 STEM 比例，等于在通识收敛后再买推理；学习率加速衰减防止把 S1 的知识冲掉。S3 不从头训 32k，是因为注意力二次成本：先 4k 买步数，再在已经成形的表示上长窗。</p><p>QK-Norm 钉住 (Q,K) 尺度，深层 94 层 MoE 与长 CoT 前缀上更不容易 softmax 饱和；去掉 QKV bias 使 2.5 权重无法热加载到 3。无共享专家迫使高频功能也走离散路由，全局 batch 负载损失用来对抗崩溃——机制取舍见 <a href="/llm/qwen3">Qwen3</a> 与 <a href="/llm/moe-routing">MoE 路由</a>。词表 151,669 相对 2.5 略增（控制符），常规 BPE 主体连续，减少「换代换 tokenizer」事故。</p><h3 id="base-变强不等于聊天变强" tabindex="-1">Base 变强不等于聊天变强 <a class="header-anchor" href="#base-变强不等于聊天变强" aria-label="Permalink to &quot;Base 变强不等于聊天变强&quot;">​</a></h3><p>报告用大量 Base 表证明预训练赢了。Instruct 的思考模式是另一套四阶段后训练。把 Base 的 MMLU 增量直接说成「Qwen3 聊天超过 2.5-72B」，会把 SFT/RL 的贡献算到 36T 头上。相反，小 Instruct 的 <code>/think</code> 来自蒸馏，也不能反过来说 36T 把 0.6B 训成了推理模型。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>36T 与 119 语种无法外部审计；PDF OCR 会把公式与表格噪声送进语言模型。S3 的 32k 加上 YaRN 的 128k 仍不是 1M——百万上下文是 2.5-1M 等专线。MoE 235B 的服务要专家并行，显存按总参数估，计算按激活估。报告中的对照含 Llama-4、DeepSeek-V3、闭源 o1 / Gemini 2.5，分数是 2025-05 快照。Instruct 表把思考档对 o1、R1、Grok-3-Beta（Think）、Gemini 2.5 Pro，非思考档对 GPT-4o、DeepSeek-V3、2.5-72B-Instruct 与 Llama-4-Maverick：那是后训练产物，用来证明融合后的两端都站得住，不能用来反推 S1 的 30T 配比。小模型若关掉思维槽，得到的是蒸馏过的直答，仍可能强于同尺寸 2.5，但旗舰思考分数不得下放到 0.6B 的发布说明。</p><p>不要把 Qwen3-Next 混合架构写进 2505 报告的默认骨架。思考预算插入的英文打断句是后训练产物，换语言未保证。tokenizer 151,669 与 2.5 接近但不相同，旧脚本写死 <code>vocab_size</code> 会在加载 3 时对不齐嵌入；控制符与 <code>/think</code> 槽位要以 3 的 <code>tokenizer_config</code> 为准。</p><p><span class="marginnote">出处：Yang 等，<em>Qwen3 Technical Report</em>，arXiv:2505.09388。产品开关与四段后训练见 <a href="/llm/qwen3">Qwen3</a>；2.5 数据规模对照见 <a href="/llm/qwen25-report">Qwen2.5 技术报告</a>。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预训练约 36T、119 种语言；PDF-VL 抽取 + 合成 STEM/代码；实例级标注配比。</li><li>三阶段：&gt;30T@4k → ~5T 推理@4k → 32k 长窗 + ABF；推理 YaRN/DCA 到约 128k。</li><li>稠密 0.6B–32B、MoE 30B-A3B / 235B-A22B；注意力无 QKV bias、有 QK-Norm；MoE 128/8、无共享专家。</li><li>Base 表显示小尺寸对上 2.5 更大档；思考融合不在本篇展开。</li><li>出处：arXiv:2505.09388。</li></ul>',13))])}const w=r(c,[["render",p]]);export{u as __pageData,w as default};
